WITH parsed AS (SELECT id, created_at, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, li) -> acc + li.qty * li.price, acc -> ROUND(acc, 2)) AS items_total, COALESCE(attributes['gift'], 'direct') AS gift_or_default, SIZE(attributes) AS num_attributes, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code FROM carts) SELECT id, created_at, gift_or_default, LAG(items_total, 1) OVER (ORDER BY created_at, id) AS prev_items_total, AVG(num_attributes) OVER (ORDER BY num_attributes, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS num_attributes_avg_6_prior FROM parsed;
